package com.fitnutri.backend.submission;

import com.fasterxml.jackson.databind.*;
import com.fitnutri.backend.activity.*;
import com.fitnutri.backend.foodreference.*;
import com.fitnutri.backend.profile.*;
import com.fitnutri.backend.records.*;
import com.fitnutri.backend.support.TestDatabase;
import com.fitnutri.backend.user.*;
import com.sun.net.httpserver.HttpServer;
import java.io.IOException;
import java.math.BigDecimal;
import java.net.*;
import java.net.http.*;
import java.sql.*;
import java.time.*;
import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.*;
import org.junit.jupiter.api.*;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.boot.test.web.server.LocalServerPort;
import org.springframework.test.context.*;
import static org.junit.jupiter.api.Assertions.*;

/** Actual reviewed POST/Session/PG transactions. The proxy drops bytes, never fabricates a business response. */
@SpringBootTest(webEnvironment=SpringBootTest.WebEnvironment.RANDOM_PORT) @ActiveProfiles("integration-test")
class SubmissionNetworkRecoveryHttpIntegrationTest {
    static final TestDatabase DB=TestDatabase.create();static{Runtime.getRuntime().addShutdownHook(new Thread(DB::close));}
    @DynamicPropertySource static void db(DynamicPropertyRegistry r){r.add("spring.datasource.url",DB::url);r.add("spring.datasource.username",DB::username);r.add("spring.datasource.password",DB::password);}
    @LocalServerPort int port;
    @Autowired UserRepository users;@Autowired AuthService auth;@Autowired ProfileService profiles;@Autowired FoodDatasetRepository foodDatasets;@Autowired FoodReferenceRepository references;@Autowired ActivityDatasetRepository activityDatasets;@Autowired ExerciseTypeRepository types;@Autowired FoodRecordRepository foods;@Autowired ExerciseRecordRepository exercises;@Autowired SubmissionReceiptRepository receipts;@Autowired CanonicalSubmissionHasher hasher;
    final ObjectMapper json=new ObjectMapper();HttpClient client;String token;Long owner;FoodReference first,second;ExerciseType activity;
    @BeforeEach void arrangeRealAccountAndSyntheticReferences() throws Exception {
        String email="network-recovery-"+UUID.randomUUID()+"@example.test";var account=auth.register(new RegisterRequest(email,"Synthetic123","Synthetic recovery test"));owner=Long.valueOf(account.id());profiles.completeOnboarding(owner,new CompleteOnboardingRequest(account.version(),null,"Synthetic recovery test",1990,true,Sex.PREFER_NOT_TO_SAY,new BigDecimal("170"),ActivityLevel.LIGHT,null,null,EnergyUnit.KJ,HealthSafetyAnswer.NO,false,"Australia/Sydney",new CompleteOnboardingRequest.InitialWeight(LocalDate.of(2020,1,1),new BigDecimal("70"))));
        var fixture=new RecordFixtureFactory(users,profiles,foodDatasets,references,activityDatasets,types);first=fixture.food("659");second=fixture.food("412");activity=fixture.exercise("3.5");client=HttpClient.newBuilder().cookieHandler(new CookieManager(null,CookiePolicy.ACCEPT_ALL)).build();token=expect(200,send("GET","/api/auth/csrf",null)).get("token").asText();expect(200,send("POST","/api/auth/login",Map.of("email",email,"password","Synthetic123")));token=expect(200,send("GET","/api/auth/csrf",null)).get("token").asText();
    }
    @AfterEach void closeClient(){if(client!=null)client.close();}
    HttpRequest request(String method,URI uri,Object body) throws Exception {var b=HttpRequest.newBuilder(uri).timeout(Duration.ofSeconds(10));if(token!=null)b.header("X-CSRF-TOKEN",token);if(body!=null)b.header("Content-Type","application/json");return b.method(method,body==null?HttpRequest.BodyPublishers.noBody():HttpRequest.BodyPublishers.ofString(json.writeValueAsString(body))).build();}
    HttpResponse<String> send(String method,String path,Object body) throws Exception {return client.send(request(method,URI.create("http://127.0.0.1:"+port+path),body),HttpResponse.BodyHandlers.ofString());}
    JsonNode expect(int status,HttpResponse<String> response) throws Exception {assertEquals(status,response.statusCode(),response.body());return response.body().isBlank()?null:json.readTree(response.body());}
    Map<String,Object> item(FoodReference reference,int grams,String meal){return new LinkedHashMap<>(Map.of("clientEntryId",UUID.randomUUID().toString(),"referenceId",reference.getId().toString(),"quantityGrams",grams,"mealType",meal));}
    Map<String,Object> batch(){return new LinkedHashMap<>(Map.of("submissionId",UUID.randomUUID().toString(),"recordDate","2020-01-02","zone","Australia/Sydney","source","MANUAL","items",List.of(item(first,150,"LUNCH"),item(second,100,"DINNER"))));}
    long count(String table) throws Exception {assertTrue(Set.of("food_record","exercise_record","submission_receipt").contains(table));try(var c=DB.connect();var p=c.prepareStatement("SELECT count(*) FROM "+table+" WHERE user_id=?")){p.setLong(1,owner);try(var r=p.executeQuery()){r.next();return r.getLong(1);}}}
    void assertHash(Map<String,Object> input){var items=new ArrayList<CanonicalSubmissionHasher.FoodItem>();for(Object value:(List<?>)input.get("items")){var row=(Map<?,?>)value;items.add(new CanonicalSubmissionHasher.FoodItem(UUID.fromString(row.get("clientEntryId").toString()),Long.valueOf(row.get("referenceId").toString()),new BigDecimal(row.get("quantityGrams").toString()),MealType.valueOf(row.get("mealType").toString())));}var expected=hasher.food(UUID.fromString(input.get("submissionId").toString()),LocalDate.parse(input.get("recordDate").toString()),input.get("zone").toString(),RecordSource.valueOf(input.get("source").toString()),items);assertEquals(expected.requestSha256(),receipts.findByUserIdAndSubmissionId(owner,expected.submissionId()).orElseThrow().getRequestSha256());}
    JsonNode receipt(Map<String,Object> request) throws Exception {return expect(200,send("GET","/api/submissions/"+request.get("submissionId"),null));}
    final class DropAfterCommitProxy implements AutoCloseable {
        final HttpServer server=HttpServer.create(new InetSocketAddress("127.0.0.1",0),0);final AtomicReference<JsonNode> firstProof=new AtomicReference<>();final AtomicInteger firstStatus=new AtomicInteger();final AtomicReference<Throwable> failure=new AtomicReference<>();final ExecutorService executor=Executors.newFixedThreadPool(2);final HttpClient upstream=HttpClient.newHttpClient();
        DropAfterCommitProxy() throws IOException {server.setExecutor(executor);server.createContext("/",exchange->{try{byte[] body=exchange.getRequestBody().readAllBytes();var b=HttpRequest.newBuilder(URI.create("http://127.0.0.1:"+port+exchange.getRequestURI())).timeout(Duration.ofSeconds(10));for(String name:List.of("Content-Type","Cookie","X-CSRF-TOKEN")){String value=exchange.getRequestHeaders().getFirst(name);if(value!=null)b.header(name,value);}var response=upstream.send(b.method(exchange.getRequestMethod(),HttpRequest.BodyPublishers.ofByteArray(body)).build(),HttpResponse.BodyHandlers.ofString());if(firstStatus.compareAndSet(0,response.statusCode()))firstProof.set(json.readTree(response.body()));}catch(Throwable e){failure.compareAndSet(null,e);}finally{exchange.close();}});server.start();}
        URI uri(String path){return URI.create("http://127.0.0.1:"+server.getAddress().getPort()+path);}
        @Override public void close(){server.stop(0);executor.shutdownNow();upstream.close();}
    }
    @Test void committedTwoFoodResponseLossRecoversProofAndReplayCannotUndoLaterCorrectionOrDeletion() throws Exception {
        var input=batch();JsonNode created;
        try(var proxy=new DropAfterCommitProxy()){assertThrows(IOException.class,()->client.send(request("POST",proxy.uri("/api/records/food/batch"),input),HttpResponse.BodyHandlers.ofString()));assertNull(proxy.failure.get());assertEquals(201,proxy.firstStatus.get());created=proxy.firstProof.get();assertNotNull(created);}
        assertEquals(2,count("food_record"));assertEquals(1,count("submission_receipt"));var proof=receipt(input);assertEquals(created.get("records"),proof.get("records"));assertEquals(2,proof.get("records").size());assertHash(input);for(var row:proof.get("records")){assertEquals(Set.of("id","clientEntryId","recordDate","versionAtCreation"),json.convertValue(row,Map.class).keySet());assertEquals(0,row.get("versionAtCreation").asInt());assertEquals(input.get("recordDate"),row.get("recordDate").asText());}assertEquals(Set.of("submissionId","kind","committedAt","replayed","records"),json.convertValue(proof,Map.class).keySet());assertTrue(proof.get("replayed").asBoolean());
        var rows=proof.get("records");String corrected=rows.get(0).get("id").asText(),deleted=rows.get(1).get("id").asText();var original=expect(200,send("GET","/api/records/food/"+corrected,null));var change=Map.of("expectedVersion",0,"referenceId",original.get("reference").get("referenceId").asText(),"quantityGrams",200,"mealType","SNACK","recordDate","2020-01-03","zone","Australia/Sydney");var updated=expect(200,send("PUT","/api/records/food/"+corrected,change));expect(204,send("DELETE","/api/records/food/"+deleted+"?expectedVersion=0",null));var replay=expect(200,send("POST","/api/records/food/batch",input));assertEquals(proof.get("records"),replay.get("records"));assertEquals(updated,expect(200,send("GET","/api/records/food/"+corrected,null)));expect(404,send("GET","/api/records/food/"+deleted,null));assertNotNull(foods.findById(Long.valueOf(deleted)).orElseThrow().getDeletedAt());assertEquals(1,foods.findById(Long.valueOf(deleted)).orElseThrow().getVersion());assertEquals(2,count("food_record"));assertEquals(1,count("submission_receipt"));
    }
    @Test void lostUnavailableExerciseResponseRecoversOriginalSnapshotEvenAfterHistoricalWeightBackfill() throws Exception {
        String day="2019-12-31";var preview=expect(200,send("GET","/api/records/exercise/estimate?exerciseTypeId="+activity.getId()+"&durationMinutes=10.5&recordDate="+day+"&zone=Australia/Sydney",null));assertEquals("MISSING_WEIGHT",preview.get("estimateStatus").asText());var input=new LinkedHashMap<String,Object>(Map.of("submissionId",UUID.randomUUID().toString(),"clientEntryId",UUID.randomUUID().toString(),"recordDate",day,"zone","Australia/Sydney","source","MANUAL","exerciseTypeId",activity.getId().toString(),"durationMinutes",10.5,"calculationFingerprint",preview.get("calculationFingerprint").asText()));
        try(var proxy=new DropAfterCommitProxy()){assertThrows(IOException.class,()->client.send(request("POST",proxy.uri("/api/records/exercise"),input),HttpResponse.BodyHandlers.ofString()));assertNull(proxy.failure.get());assertEquals(201,proxy.firstStatus.get());}
        var proof=receipt(input);String id=proof.get("records").get(0).get("id").asText();var before=expect(200,send("GET","/api/records/exercise/"+id,null));assertTrue(before.get("estimatedKj").isNull());assertEquals(10.5,before.get("durationMinutes").asDouble());var weight=new LinkedHashMap<String,Object>();weight.put("recordDate","2019-12-30");weight.put("weightKg",68.5);weight.put("expectedVersion",null);weight.put("zone","Australia/Sydney");expect(201,send("POST","/api/profile/weight",weight));var replay=expect(200,send("POST","/api/records/exercise",input));assertEquals(proof.get("records"),replay.get("records"));assertEquals(before,expect(200,send("GET","/api/records/exercise/"+id,null)));assertEquals(1,count("exercise_record"));assertEquals(1,count("submission_receipt"));
    }
    @Test void actualInFlightPostCanHaveReceipt404BeforeLockReleaseThenCommitOnceWithTheOriginalIds() throws Exception {
        var input=batch();try(var locker=DB.connect();var pool=Executors.newSingleThreadExecutor()){locker.setAutoCommit(false);try(var s=locker.prepareStatement("SELECT id FROM app_user WHERE id=? FOR UPDATE")){s.setLong(1,owner);s.executeQuery().close();}var future=pool.submit(()->send("POST","/api/records/food/batch",input));try{assertTrue(awaitOwnerLockWait(),"The actual POST must be waiting inside PostgreSQL, not merely queued in the test.");assertFalse(future.isDone());expect(404,send("GET","/api/submissions/"+input.get("submissionId"),null));assertEquals(0,count("food_record"));assertEquals(0,count("submission_receipt"));}finally{locker.commit();}var committed=expect(201,future.get(15,TimeUnit.SECONDS));assertEquals(committed.get("records"),receipt(input).get("records"));var replay=expect(200,send("POST","/api/records/food/batch",input));assertEquals(committed.get("records"),replay.get("records"));assertEquals(2,count("food_record"));assertEquals(1,count("submission_receipt"));}
    }
    boolean awaitOwnerLockWait() throws Exception {long deadline=System.nanoTime()+TimeUnit.SECONDS.toNanos(5);while(System.nanoTime()<deadline){try(var c=DB.connect();var s=c.createStatement();var r=s.executeQuery("SELECT count(*) FROM pg_stat_activity WHERE datname=current_database() AND wait_event_type='Lock' AND query LIKE '%app_user%'")){r.next();if(r.getInt(1)>0)return true;}Thread.sleep(20);}return false;}
    @Test void twoRealHttpRequestsWithOneIdAndPayloadReturnOne201One200AndOneAtomicBatch() throws Exception {var input=batch();var start=new CountDownLatch(1);try(var pool=Executors.newFixedThreadPool(2)){Callable<HttpResponse<String>> work=()->{start.await();return send("POST","/api/records/food/batch",input);};var a=pool.submit(work);var b=pool.submit(work);start.countDown();var one=a.get(15,TimeUnit.SECONDS);var two=b.get(15,TimeUnit.SECONDS);assertEquals(Set.of(201,200),new HashSet<>(List.of(one.statusCode(),two.statusCode())));assertEquals(json.readTree(one.body()).get("records"),json.readTree(two.body()).get("records"));assertEquals(2,count("food_record"));assertEquals(1,count("submission_receipt"));}}
    @Test void concurrentDifferentPayloadsWithOneSubmissionIdHaveOneWinnerAndNoPartialLoser() throws Exception {var one=batch();var two=new LinkedHashMap<>(one);var items=new ArrayList<Map<String,Object>>();for(Object value:(List<?>)one.get("items")){var row=new LinkedHashMap<String,Object>();((Map<?,?>)value).forEach((k,v)->row.put(k.toString(),v));items.add(row);}items.get(0).put("quantityGrams",200);two.put("items",items);var start=new CountDownLatch(1);try(var pool=Executors.newFixedThreadPool(2)){var a=pool.submit(()->{start.await();return send("POST","/api/records/food/batch",one);});var b=pool.submit(()->{start.await();return send("POST","/api/records/food/batch",two);});start.countDown();var first=a.get(15,TimeUnit.SECONDS);var second=b.get(15,TimeUnit.SECONDS);assertEquals(Set.of(201,409),new HashSet<>(List.of(first.statusCode(),second.statusCode())));var rejected=first.statusCode()==409?first:second;assertEquals("IDEMPOTENCY_CONFLICT",json.readTree(rejected.body()).get("code").asText());var winner=first.statusCode()==201?one:two;assertHash(winner);var winnerItems=(List<?>)winner.get("items");for(var record:foods.findByUserIdOrderByRecordedAtDesc(owner)){var submitted=winnerItems.stream().map(v->(Map<?,?>)v).filter(v->v.get("clientEntryId").equals(record.getClientEntryId().toString())).findFirst().orElseThrow();assertEquals(0,record.getQuantityGramsSnapshot().compareTo(new BigDecimal(submitted.get("quantityGrams").toString())));}assertEquals(2,count("food_record"));assertEquals(1,count("submission_receipt"));}}
}
